Definition icpt_postF (RT : rt_sig) (Σ : rts RT) (PMc : Model -> Prop) (F : bvmap 5 word)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 v : word) (lo d n : Z) (m : mem) (Q : mem -> Prop) : config -> Prop :=
  ASTA RT Σ PMc (fun ms => exists m', ret_stF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 v F m' ms
                    /\ rt_after RT Σ (bv_unsigned sp) lo m m'
