(* [comment removed for export] *)
Ltac fk_go :=
  cbv beta in *;
  repeat match goal with
  | H : exists _, _ |- _ => destruct H
  | H : _ /\ _ |- _ => destruct H
  end;
  repeat first
    [ eassumption
    | match goal with
      | HA : ASTA _ _ _ _ ?c |- ASTA _ _ _ _ ?c =>
          eapply ASTA_conseq; [exact HA|]; clear HA; let ms := fresh "ms" in let Hms := fresh "Hms" in intros ms Hms; fk_go
      | HR : ret_stF _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?ms |- ret_st _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ ?ms =>
          exact (ret_stF_ret_st _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HR)
      | |- exists _, _ => eexists
      | |- _ /\ _ => split
      end ].
Ltac fk_post :=
  let c := fresh "c" in let Hc := fresh "Hc" in intros c Hc;
  unfold malloc_postF, malloc_post, free_postF, free_post, icpt_postF, icpt_post in *; fk_go.

